			_elemPool = new ElementPool(MaxFrame);
			_trailWidth = (PointStart.position - PointEnd.position).magnitude;
			var rendererObject=new GameObject("OldSaber.ClassicTrail");
            UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(rendererObject,gameObject.scene);
            _trailRenderer=rendererObject.AddComponent<XWeaponTrailRenderer>();
            _trailRenderer.Initialize(MyMaterial,gameObject.layer);
			_vertexPool = new VertexPool(_trailRenderer.mesh);
			_vertexSegment = _vertexPool.GetVertices(Granularity * 3, (Granularity - 1) * 12);
			UpdateIndices();
			_spline.Granularity = Granularity;
		}

		private void OnEnable()
