				_trailRenderer.enabled = false;
			}
		}

		private void LateUpdate()
		{
			_frameNum++;
			if (_frameNum == _skipFirstFrames + 1)
			{
				if ((bool)_trailRenderer)
				{
					_trailRenderer.enabled = true;
				}
				_spline.Clear();
